14:   let [r,g,b] = hexToRgb(hex).map(v=>v/255);
15:   const max = Math.max(r,g,b), min = Math.min(r,g,b);
16:   let h=0, s=0, l=(max+min)/2;
17:   if (max !== min) {
18:     const d = max-min;
19:     s = l > .5 ? d/(2-max-min) : d/(max+min);
20:     h = max===r ? ((g-b)/d+(g<b?6:0)) : max===g ? ((b-r)/d+2) : ((r-g)/d+4);
